const queryId = $input.first().json.query?.id;
const directId = $input.first().json.id;
const id = queryId || directId || '';
const fechaEnvio = new Date().toISOString();
if (!id) throw new Error('No se encontró ID de oferta: ' + JSON.stringify($input.first().json));
return [{ json: { id, fechaEnvio } }];

return $input.all().map((item, idx) => {
  const d = item.json;

  const titleProp = Object.values(d.properties || {}).find(p => p.type === 'title');
  const empresa = titleProp?.title?.[0]?.plain_text || titleProp?.title?.[0]?.text?.content || 'Sin nombre';

  // Email del usuario: 1º del nodo que lo grabó (valor probado), 2º la página, 3º fallback
  let email = '';
  try {
    const src = $('Code - Normalizar Modalidad').all();
    const j = (src[idx] || src[0] || {}).json || {};
    if (j.email_usuario && j.email_usuario.includes('@')) email = j.email_usuario;
  } catch (_) {}
  if (!email) {
    const emailPropNotion = d.properties?.['Email Enviado'] || d.properties?.['Email usuario'];
    email = emailPropNotion?.email
      || emailPropNotion?.rich_text?.[0]?.plain_text
      || d.email_usuario
      || 'hello.cookyourweb@gmail.com';
  }

  const puesto     = d.properties?.Puesto?.rich_text?.[0]?.plain_text || '';
  const salario    = d.properties?.Salario?.rich_text?.[0]?.plain_text || '';
  const modalidad  = d.properties?.Modalidad?.select?.name || '';
  const notas      = d.properties?.Notas?.rich_text?.[0]?.plain_text || '';
  const linkOferta = d.properties?.['Link oferta']?.url || '';
  const pageId     = d.id || '';
  const nombreContacto = d.properties?.['Nombre Contacto']?.rich_text?.[0]?.plain_text || '';
  const emailContacto  = d.properties?.['Email empresa']?.email || '';

  const htmlContent = '<div style="font-family:Arial;padding:20px;max-width:600px">'
    + '<h2 style="color:#1F5C8B">' + empresa + '</h2>'
    + '<p><b>Puesto:</b> ' + puesto + '</p>'
    + '<p><b>Salario:</b> ' + salario + '</p>'
    + '<p><b>Modalidad:</b> ' + modalidad + '</p>'
    + '<p>' + notas + '</p>'
    + (nombreContacto ? '<p><b>Contacto:</b> ' + nombreContacto + '</p>' : '')
    + (emailContacto  ? '<p><b>Email empresa:</b> ' + emailContacto + '</p>' : '')
    + (linkOferta ? '<p><a href="' + linkOferta + '" style="color:#1F5C8B;font-weight:bold;text-decoration:underline" target="_blank">🔗 Ver oferta completa</a></p>' : '')
    + '<br><a href="https://n8n-asistente-correo.onrender.com/webhook/@@SECRET:Webhook Aprobar?id=' + pageId
    + '" style="background:#22C55E;color:white;padding:12px 24px;text-decoration:none;border-radius:6px;font-weight:bold;display:inline-block">Aprobar</a> '
    + '<a href="https://n8n-asistente-correo.onrender.com/webhook/@@SECRET:Webhook Descartar?id=' + pageId
    + '" style="background:#EF4444;color:white;padding:12px 24px;text-decoration:none;border-radius:6px;font-weight:bold;display:inline-block;margin-left:12px">Descartar</a>'
    + '</div>';

  const brevoBody = JSON.stringify({
    sender: {name: 'Verónica Serna', email: 'veronica@cookyourwebai.es'},
    to: [{email: email}],
    subject: 'Nueva oferta: ' + empresa + ' - ' + puesto,
    htmlContent: htmlContent,
    trackClicks: false,
    trackOpens: false
  });

  return { json: { empresa, puesto, salario, modalidad, pageId, email, linkOferta, brevoBody } };
});

const response = $input.first().json;

if (response.error) {
  throw new Error('Groq API error: ' + JSON.stringify(response.error));
}

const text = response.choices?.[0]?.message?.content || '';
if (!text) {
  throw new Error('Respuesta vacía: ' + JSON.stringify(response).substring(0, 300));
}

const jsonMatch = text.match(/\[[\s\S]*\]/);
if (!jsonMatch) {
  throw new Error('No se encontró array JSON. Texto: ' + text.substring(0, 500));
}

let ofertas;
try { ofertas = JSON.parse(jsonMatch[0]); }
catch (e) { throw new Error('JSON inválido: ' + e.message); }
// A model sometimes echoes the empty template instead of []: keep only real offers.
ofertas = (Array.isArray(ofertas) ? ofertas : []).filter(o => o && String(o.link || '').trim());

// Recuperar email_usuario Y user_id del nodo que alimentó el Wait
let emailUsuario = '';
let userId = '';
try {
  emailUsuario = $('Formatear ofertas').first().json.email_usuario || '';
  userId = $('Formatear ofertas').first().json.user_id || '';
} catch(e) {}
if (!emailUsuario || !userId) {
  const nodosOrigen = ['Code — Normalizar (interno)', 'Code — Normalizar users (schedule)'];
  for (const nodo of nodosOrigen) {
    if (emailUsuario && userId) break;
    try {
      const d = $(nodo).first().json;
      if (!emailUsuario) emailUsuario = d.email_usuario || d.email || '';
      if (!userId) userId = d.user_id || '';
    } catch(e) {}
  }
}

// Idioma detectado de la descripción REAL en "Formatear ofertas", indexado por link
let idiomaPorLink = {};
try { idiomaPorLink = $('Formatear ofertas').first().json.idioma_por_link || {}; } catch(e) {}
let ubicacionPorLink = {};
try { ubicacionPorLink = $('Formatear ofertas').first().json.ubicacion_por_link || {}; } catch(e) {}
let descripcionPorLink = {};
try { descripcionPorLink = $('Formatear ofertas').first().json.descripcion_por_link || {}; } catch(e) {}

return ofertas.map(oferta => {
  const linkKey = String(oferta.link || '').trim();
  const desc = String(descripcionPorLink[linkKey] || '');
  const ubic = String(ubicacionPorLink[linkKey] || '');

  // Señales de modalidad: lo que dijo Groq (suele venir vacío porque solo ve 60
  // chars) MÁS la descripción completa de 1800 chars que ya se guarda aquí al lado.
  // El RSS de Tecnoempleo mete la modalidad en el campo Provincia: "Provincia: hibrido",
  // "Provincia: 100% en remoto". Medido sobre el feed: 26 de 80 ofertas lo hacen así.
  const senales = ((oferta.modalidad || '') + ' ' + desc + ' ' + ubic).toLowerCase();

  // NUNCA se asume la modalidad. Si la oferta no lo dice, queda Sin confirmar y
  // entra igual, para que Vero abra el link y decida. Medido: 31 de 80 ofertas
  // del feed no dicen la modalidad en ninguna parte. Asumir Presencial las tiraba
  // todas, que era el motivo real de que no llegase nada a Notion.
  let modalidad = 'Sin confirmar';
  if (/100\s*%\s*(en\s+)?remoto|full\s*remote|fully\s*remote/.test(senales)) modalidad = 'Remoto';
  else if (/h[ií]brido|hybrid/.test(senales)) modalidad = 'Hibrido';
  else if (/\bremoto\b|teletrabajo|\bremote\b/.test(senales)) modalidad = 'Remoto';
  else if (/presencial|on-?site|in-?office/.test(senales)) modalidad = 'Presencial';

  // Per-user cities (design 2026-11-01). Base city tokens ("Valdemorillo, Madrid")
  // plus every "Híbrido <city>" in the user's modalidades. BCN is an alias of Barcelona.
  const UF = (() => { try { return $('Formatear ofertas').first().json; } catch (e) { return {}; } })();
  const ALIAS = { bcn: 'barcelona' };
  const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const mods = (UF.modalidad || []).map(norm);
  const base = norm(UF.ciudad).split(',').map(s => s.trim()).filter(Boolean);
  const hibOcasional = mods.filter(m => m.startsWith('hibrido ')).map(m => m.slice(8).trim())
    .map(c => ALIAS[c] || c).filter(c => !base.includes(c));
  const aceptaHibrido = mods.some(m => m.startsWith('hibrido'));
  const aceptaPresencial = mods.some(m => m.startsWith('presencial'));
  const texto = norm(ubic + ' ' + desc);
  const enBase = base.some(c => texto.includes(c));
  const enOcasional = hibOcasional.some(c => texto.includes(c));

  // Se descarta SOLO con dato explícito. Lo desconocido pasa marcado.
  if (modalidad === 'Presencial' && !(aceptaPresencial && enBase)) return null;
  const sinCiudad = /confirmar ciudad/i.test(String(oferta.notas || ''));
  if (modalidad === 'Hibrido' && !(aceptaHibrido && (enBase || enOcasional || sinCiudad))) return null;

  const emailContacto = oferta.email_contacto && oferta.email_contacto.includes('@')
    ? oferta.email_contacto : '';

  const idioma = idiomaPorLink[linkKey] || '';

  // Aviso visible en Notas cuando la modalidad no se ha podido confirmar.
  const aviso = modalidad === 'Sin confirmar' ? '[VERIFICAR MODALIDAD] ' : '';

  return { json: {
    email_usuario:     emailUsuario,
    user_id:           userId,
    empresa:           oferta.empresa || 'Sin nombre',
    puesto:            oferta.puesto || '',
    salario:           oferta.salario || '',
    modalidad,
    ubicacion:         ubic || '',
    link:              oferta.link || '',
    descripcion_corta: aviso + (oferta.notas ? oferta.notas + ' · ' : '') + (oferta.descripcion_corta || ''),
    descripcion_full:  descripcionPorLink[linkKey] || oferta.descripcion_corta || '',
    idioma,
    nombre_contacto:   oferta.nombre_contacto || '',
    email_contacto:    emailContacto,
    telefono_contacto: oferta.telefono_contacto || '',
    fecha_publicacion: oferta.fecha_publicacion || ''
  }};
}).filter(x => x !== null);

